     1	export type WorkStatus = 'pending' | 'in_progress' | 'blocked' | 'done'
     2	export type SourceKind = 'outlook_email' | 'teams_message' | 'manual'
     3	
     4	export interface WorkItem { id: string; title: string; summary: string | null; status: WorkStatus; source_kind: SourceKind; source_external_id: string | null; source_url: string | null; assigned_agent: string | null; due_at: string | null; created_at: string; updated_at: string; evidence?: Evidence[] }
     5	export interface Evidence { id?: string; source_kind: SourceKind; external_id: string; excerpt: string | null; observed_at: string }
     6	export interface Health { status: string; service: string }
     7	
     8	export class ApiError extends Error { constructor(public status: number) { super(`Request failed (${status})`) } }
     9	let csrfToken: string | null = null
    10	
    11	async function request<T>(path: string, init?: RequestInit): Promise<T> {
    12	  const method = (init?.method ?? 'GET').toUpperCase()
    13	  const headers: Record<string, string> = { ...(init?.body ? { 'Content-Type': 'application/json' } : {}), ...(init?.headers as Record<string, string> | undefined) }
    14	  if (!['GET', 'HEAD', 'OPTIONS'].includes(method) && csrfToken) headers['X-CSRF-Token'] = csrfToken
    15	  const response = await fetch(path, { ...init, headers, credentials: 'same-origin' })
    16	  if (!response.ok) throw new ApiError(response.status)
    17	  return response.status === 204 ? ({} as T) : response.json() as Promise<T>
    18	}
    19	
    20	export async function startLocalSession(localToken: string): Promise<void> {
    21	  const response = await fetch('/api/session', { method: 'POST', credentials: 'same-origin', headers: { Authorization: `Bearer ${localToken}` } })
    22	  if (!response.ok) throw new ApiError(response.status)
    23	  csrfToken = (await response.json() as { csrf_token: string }).csrf_token
    24	}
    25	
    26	export async function restoreLocalSession(): Promise<void> {
    27	  const response = await fetch('/api/session', { credentials: 'same-origin' })
    28	  if (!response.ok) throw new ApiError(response.status)
    29	  csrfToken = (await response.json() as { csrf_token: string }).csrf_token || null
    30	}
    31	
    32	export const beginMicrosoftConnect = async () => {
    33	  const response = await request<{ authorization_url: string }>('/api/auth/microsoft/start')
    34	  window.location.assign(response.authorization_url)
    35	}
    36	export const syncNow = () => request<{ created?: number; updated?: number; detail?: string }>('/api/sync', { method: 'POST' })
    37	export const createDispatch = (id: string, client: 'codex' | 'claude-code', instruction: string) => request(`/api/work-items/${id}/dispatch`, { method: 'POST', body: JSON.stringify({ client, instruction }) })
    38	
    39	export const getHealth = () => request<Health>('/api/health')
    40	export const getWorkItems = () => request<WorkItem[]>('/api/work-items')
    41	export const getWorkItem = (id: string) => request<WorkItem>(`/api/work-items/${id}`)
    42	export const updateWorkItem = (id: string, update: Partial<Pick<WorkItem, 'status' | 'assigned_agent'>>) => request<WorkItem>(`/api/work-items/${id}`, { method: 'PATCH', body: JSON.stringify(update) })
