     1	import { useEffect, useMemo, useState, type FormEvent } from 'react'
     2	import { ApiError, beginMicrosoftConnect, createDispatch, getHealth, getWorkItem, getWorkItems, restoreLocalSession, startLocalSession, syncNow, updateWorkItem, type SourceKind, type WorkItem, type WorkStatus } from './api'
     3	
     4	const demoItems: WorkItem[] = [
     5	  { id: 'demo-email', title: 'Send the revised project estimate', summary: 'The client asked for an updated estimate before Friday.', status: 'pending', source_kind: 'outlook_email', source_external_id: 'demo-001', source_url: null, assigned_agent: null, due_at: null, created_at: '', updated_at: '', evidence: [{ source_kind: 'outlook_email', external_id: 'demo-001', excerpt: 'Could you send the revised estimate before Friday?', observed_at: '' }] },
     6	  { id: 'demo-teams', title: 'Confirm the rollout owner', summary: 'A decision is needed in the launch channel.', status: 'blocked', source_kind: 'teams_message', source_external_id: 'demo-002', source_url: null, assigned_agent: 'Codex', due_at: null, created_at: '', updated_at: '', evidence: [{ source_kind: 'teams_message', external_id: 'demo-002', excerpt: 'We still need an owner for the rollout checklist.', observed_at: '' }] },
     7	  { id: 'demo-manual', title: 'Review next week’s priorities', summary: 'Prepare the work plan for the team check-in.', status: 'in_progress', source_kind: 'manual', source_external_id: null, source_url: null, assigned_agent: null, due_at: null, created_at: '', updated_at: '', evidence: [] },
     8	]
