    13	export default function App() {
    14	  const [items, setItems] = useState<WorkItem[]>([]); const [selected, setSelected] = useState<WorkItem | null>(null); const [filter, setFilter] = useState<WorkStatus | 'all'>('all'); const [source, setSource] = useState<SourceKind | 'all'>('all'); const [query, setQuery] = useState(''); const [state, setState] = useState<'checking' | 'ready' | 'offline'>('checking'); const [demo, setDemo] = useState(false); const [settings, setSettings] = useState(false); const [toast, setToast] = useState(''); const [locked, setLocked] = useState(false); const [localToken, setLocalToken] = useState('')
    15	  const loadWork = async () => { try { await getHealth(); await restoreLocalSession(); const work = await getWorkItems(); setState('ready'); setLocked(false); setDemo(false); setItems(work); setSelected(work[0] ?? null) } catch (error) { if (error instanceof ApiError && (error.status === 401 || error.status === 503)) { setState('offline'); setLocked(true); return } setState('offline'); setDemo(true); setItems(demoItems); setSelected(demoItems[0]) } }
    16	  useEffect(() => { void loadWork() }, [])
    17	  const unlock = async (event: FormEvent) => { event.preventDefault(); try { await startLocalSession(localToken); setLocalToken(''); await loadWork() } catch { setToast('That local token could not unlock Magic Tower.') } }
    18	  const connectMicrosoft = async () => { try { await beginMicrosoftConnect() } catch { setToast('Microsoft connection could not start.') } }
    19	  const runSync = async () => { try { const result = await syncNow(); await loadWork(); setToast(result.detail || 'Microsoft messages synced.') } catch { setToast('Sync could not be completed.') } }
    20	  const handoff = async (item: WorkItem, client: 'codex' | 'claude-code') => { try { await createDispatch(item.id, client, 'Review the local Magic Tower item and propose the next safe action.'); setToast(`Queued a ${client} handoff.`) } catch { setToast('Could not queue the agent handoff.') } }
    21	  const visible = useMemo(() => items.filter(i => (filter === 'all' || i.status === filter) && (source === 'all' || i.source_kind === source) && `${i.title} ${i.summary ?? ''}`.toLowerCase().includes(query.toLowerCase())), [items, filter, source, query])
    22	  const showDemo = () => { setDemo(true); setItems(demoItems); setSelected(demoItems[0]); setToast('Showing sample items — connect the API for your work queue.') }
    23	  const choose = async (item: WorkItem) => { setSelected(item); if (!demo) try { setSelected(await getWorkItem(item.id)) } catch { /* list summary remains usable */ } }
    24	  const changeStatus = async (status: WorkStatus) => { if (!selected) return; const old = selected; const next = { ...old, status }; setSelected(next); setItems(all => all.map(i => i.id === next.id ? next : i)); if (!demo) try { const saved = await updateWorkItem(old.id, { status }); setSelected(saved); setItems(all => all.map(i => i.id === saved.id ? saved : i)) } catch { setSelected(old); setItems(all => all.map(i => i.id === old.id ? old : i)); setToast('Could not save that change.') } }
    25	  return <main><header className="topbar"><div className="brand"><img src="/magic-tower-logo.png" alt="Magic Tower" /><div><h1>Magic Tower</h1><p>A private task grimoire</p></div></div><div><b className={`connection ${state}`}>{state === 'ready' ? '● Synced locally' : state === 'checking' ? 'Reading the stars' : '● Offline'}</b><button className="icon" onClick={() => setSettings(true)} aria-label="Settings">⚙</button></div></header>{toast && <div className="toast">{toast}<button onClick={() => setToast('')} aria-label="Dismiss notification">×</button></div>}<section className="intro"><div><p className="eyebrow">KEEP THE THREADS IN SIGHT</p><h2>Gather every signal.<br />Choose the next spell.</h2><p>Review tasks found in Outlook and Teams. Nothing is sent to an agent until you choose.</p></div><div className="sync">{locked ? <form onSubmit={unlock}><b>Unlock Magic Tower</b><small>Enter LOCAL_API_TOKEN for this browser session only.</small><input type="password" value={localToken} onChange={e => setLocalToken(e.target.value)} autoComplete="off" required /><button type="submit">Unlock</button></form> : <><b>✦ Scrying pool ready</b><small>{state === 'ready' ? `${items.length} work items in your queue` : 'Microsoft Graph is not connected'}</small><div className="sync-actions"><button onClick={runSync}>Sync now</button><button onClick={connectMicrosoft}>Connect Microsoft</button><button onClick={showDemo}>View sample</button></div></>}</div></section><nav className="summary">{(['all', ...statuses] as const).map(s => <button key={s} className={filter === s ? 'active' : ''} onClick={() => setFilter(s)}><strong>{s === 'all' ? items.length : items.filter(i => i.status === s).length}</strong>{s === 'all' ? 'All work' : labels[s]}</button>)}</nav><section className="workspace"><aside className="queue"><div className="tools"><input value={query} onChange={e => setQuery(e.target.value)} placeholder="⌕  Search tasks" /><select value={source} onChange={e => setSource(e.target.value as SourceKind | 'all')}><option value="all">All sources</option><option value="outlook_email">Outlook</option><option value="teams_message">Teams</option><option value="manual">Manual</option></select></div><p className="queue-title">Tower queue <small>{visible.length} items</small></p>{visible.map(i => <button className={`work ${selected?.id === i.id ? 'selected' : ''}`} onClick={() => choose(i)} key={i.id}><i className={i.source_kind} /><span><b>{i.title}</b><small>{i.summary || 'No summary yet'}</small><em>{sourceLabels[i.source_kind]}</em></span><mark className={i.status}>{labels[i.status]}</mark></button>)}{!visible.length && <p className="empty">No tasks match these filters.</p>}</aside><article className="detail">{selected ? <Detail item={selected} demo={demo} status={changeStatus} toast={setToast} handoff={handoff} /> : <div className="empty-detail"><h3>{locked ? 'Unlock Magic Tower to view your queue.' : 'Your tower is quiet.'}</h3><p>{locked ? 'The local token is never saved in this browser.' : 'Connect Microsoft Graph or explore the sample queue.'}</p><button onClick={showDemo}>Explore sample tasks</button></div>}</article></section>{settings && <Settings ready={state === 'ready'} close={() => setSettings(false)} />}</main>
    26	}
    27	function Detail({ item, demo, status, toast, handoff }: { item: WorkItem; demo: boolean; status: (v: WorkStatus) => void; toast: (v: string) => void; handoff: (item: WorkItem, client: 'codex' | 'claude-code') => void }) { const [agent, setAgent] = useState<'codex' | 'claude-code' | null>(null); const command = `scripts/pending-work context ${item.id}`; const copy = async () => { await navigator.clipboard?.writeText(command); toast('Safe context command copied. Paste it into your agent terminal.') }; const chooseAgent = (client: 'codex' | 'claude-code') => { setAgent(client); if (!demo) handoff(item, client) }; return <><div className="detail-top"><b className={`badge ${item.source_kind}`}>{sourceLabels[item.source_kind]}</b><small>Updated just now</small></div><h3>{item.title}</h3><p className="detail-summary">{item.summary || 'No summary was added to this task.'}</p><div className="status"><label>Status<select value={item.status} onChange={e => status(e.target.value as WorkStatus)}>{statuses.map(s => <option key={s} value={s}>{labels[s]}</option>)}</select></label>{item.assigned_agent && <span>Assigned to {item.assigned_agent}</span>}</div><section><h4>Why this is here <small>Source evidence</small></h4>{item.evidence?.length ? item.evidence.map((e, n) => <blockquote key={n}>{e.excerpt}<footer>{sourceLabels[e.source_kind]} conversation</footer></blockquote>) : <p className="quiet">This task was added manually, so no message evidence is available.</p>}</section><section className="handoff"><p className="eyebrow">AGENT HANDOFF</p><h4>Invite an agent to take this on</h4><p>Magic Tower records a bounded handoff and copies only the task ID. It never puts mailbox text in a shell command.</p><button onClick={() => chooseAgent('codex')}>Use Codex</button><button className="secondary" onClick={() => chooseAgent('claude-code')}>Use Claude Code</button>{agent && <div className="command"><code>{command}</code><button onClick={copy}>Copy command</button>{demo && <small>Sample item only — nothing will be dispatched.</small>}</div>}</section></> }
    28	function Settings({ ready, close }: { ready: boolean; close: () => void }) { return <div className="backdrop" onMouseDown={close}><section className="modal" onMouseDown={e => e.stopPropagation()}><button className="close" onClick={close} aria-label="Close settings">×</button><p className="eyebrow">SETTINGS</p><h3>Your connections</h3><div><b>Microsoft Graph</b><p>{ready ? 'Connected to your local Magic Tower API.' : 'Not connected. Your mail and Teams stay private until you explicitly authorize access.'}</p><mark>{ready ? 'Ready' : 'Not connected'}</mark></div><div><b>Agent handoff</b><p>Codex and Claude Code commands are always shown for review; Magic Tower never launches them.</p></div><button onClick={close}>Done</button></section></div> }
