@import "tailwindcss";

:root {
  --background: #17111f;
  --foreground: #f5edf7;
  --card: #211828;
  --card-foreground: #f5edf7;
  --popover: #241a2d;
  --popover-foreground: #f5edf7;
  --primary: #d5a94f;
  --primary-foreground: #1b1221;
  --secondary: #30243a;
  --secondary-foreground: #f2cd80;
  --muted: #2a1f32;
  --muted-foreground: #c3afc9;
  --accent: #352640;
  --accent-foreground: #f8eff5;
  --destructive: #f0917c;
  --border: #4b3854;
  --input: #5d4b65;
  --ring: #e4ba67;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  body {
    min-width: 320px;
    font-family: Inter, ui-sans-serif, system-ui, sans-serif;
    color: var(--color-foreground);
    background-color: var(--color-background);
    background-image: radial-gradient(circle at 12% 0, #3a2447 0, transparent 31rem),
      radial-gradient(circle at 92% 18%, #272445 0, transparent 28rem);
  }
}

import { clsx, type ClassValue } from 'clsx'
